        rx_expect(8'h43, 8'hff);
        rx_expect(8'h01, 8'hff);
        rx_expect(8'h11, 8'hff);
        rx_expect(8'h13, 8'hff);
        rx_expect(8'h02, 8'hff);
        rx_expect(8'h00, 8'hff);
        rx_expect(8'h04, 8'hff);
        rx_expect(8'h00, 8'hff);
        rx_expect(8'had, 8'hff);
        rx_expect(8'h91, 8'hff);
        rx_expect(8'h8b, 8'hff);
        rx_expect(8'hbc, 8'hff);
        rx_expect(8'h00, 8'hff);
        rx_expect(8'h14, 8'hff);
